const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="${icons[name]||''}"/></svg>`;
const sections=[['hub','Hub Immobilier','hub','Tous les biens publiés'],['biens','Mes biens','home','Vos dossiers vendeurs'],['recherches','Mes recherches','search','Vos acquéreurs accompagnés'],['reseau','Mon Réseau','users','Votre carnet professionnel'],['notes','Mes Notes','note','Comptes rendus et idées'],['taches','Mes Tâches','task','Vos prochaines actions']];
const link=(route,label,cls='')=>`<a class="${cls}" href="#/${route==='accueil'?'':route}">${esc(label)}</a>`;
const property=id=>demoProperties.find(p=>p.id===id);
const mine=p=>p?.agentId===currentAgentId;
const myProperties=()=>demoProperties.filter(mine);
const agent=p=>demoAgents.find(a=>a.id===p.agentId);
const propertyRoute=p=>mine(p)?'bien/'+p.id:'fiche/'+p.id;
const allContacts=()=>[...demoContacts,...state.contacts];
const person=id=>allContacts().find(c=>c.id===id);
const searchFile=id=>demoSearches.find(s=>s.id===id);
// Business colours are kept to badges and markers; each tone is a soft tint defined in styles.css.
const tones={'Brouillon':'grey','Publié':'green','À actualiser':'amber','Sous offre':'orange','Retiré':'grey','Vendu':'navy','Mon bien':'navy','Prévue':'blue','Réalisée':'grey','Intéressé':'green','Contre-visite':'violet','À recontacter':'amber','Refus':'red','Offre':'orange','Favori':'rose','Refusé':'red','Visite programmée':'blue','Offre en cours':'orange','À découvrir':'grey','À faire':'blue','En cours':'amber','Terminée':'green','Haute':'red','Normale':'grey','Basse':'grey','Confirmée':'green','Indisponible':'red','Visite proposée':'blue','Recherche active':'green','Client':'navy','Prospect':'blue','Acquéreur':'green','Propriétaire':'sand','Investisseur':'violet','Apporteur':'orange','Partenaire':'teal','Professionnel':'slate','Collègue':'rose','Autre':'grey','Exclusif':'navy','Simple':'slate'};
const pill=(text,tone=tones[text]||'')=>`<span class="pill ${tone?'t-'+tone:''}">${esc(text)}</span>`;
const addButton=(kind,label,ctx={},cls='primary')=>`<button type="button" data-add="${kind}" data-property="${esc(ctx.property||'')}" data-search="${esc(ctx.search||'')}" data-contact="${esc(ctx.contact||'')}" class="${cls}">${label}</button>`;
const button=(kind,label,id='')=>addButton(kind,label,{property:id});
const heading=(title,copy,actions='',eyebrow='')=>`<div class="page-heading"><div>${eyebrow?`<p class="eyebrow">${esc(eyebrow)}</p>`:''}<h1>${esc(title)}</h1>${copy?`<p>${esc(copy)}</p>`:''}</div><div class="actions">${actions}</div></div>`;
const panelHead=(title,actions='',id='')=>`<div class="panel-head"${id?` id="${id}"`:''}><h2>${esc(title)}</h2>${actions?`<div class="actions">${actions}</div>`:''}</div>`;
const art=p=>`<div class="property-art ${p.color}" role="img" aria-label="Illustration de ${esc(p.type)}">${icon(p.type==='Maison'?'home':'building')}<small>Photos à venir</small></div>`;
const storageKey='lila-v2-demo-workspace-v1';
const visitStatuses=['Prévue','Réalisée','Intéressé','Contre-visite','À recontacter','Refus','Offre'];
const taskStatuses=['À faire','En cours','Terminée'];
const priorities=['Normale','Haute','Basse'];
const initials=name=>String(name||'?').split(/\s+/).filter(Boolean).slice(0,2).map(w=>w[0]).join('').toUpperCase();
const avatar=c=>`<span class="avatar t-${tones[c.typology]||'grey'}" aria-hidden="true">${esc(initials(c.name))}</span>`;
const initialState=()=>({
 schema:2,viewMode:'pro',
 visits:[...demoVisitors.map(v=>({...v,contact:v.id,date:'2026-10-'+({lea:'24',hugo:'23',ines:'25',paul:'22',sarah:'26',alice:'25'}[v.id]),time:({lea:'14:00',hugo:'11:00',ines:'10:00',paul:'16:00',sarah:'15:00',alice:'17:00'}[v.id]),comment:v.note})),{id:'seller-proposed',property:'pessac',contact:'lea',name:'Léa Martin',status:'Prévue',date:'2026-10-29',time:'14:00',comment:'Créneau proposé à la propriétaire.',offer:null,sellerResponse:'Visite proposée'}],
 notes:[...demoVisitors.map(v=>({id:'note-'+v.id,title:'Visite · '+v.name,body:v.note,property:v.property,contact:v.id,created:'2026-10-26T15:00:00'})),...searchSeedNotes()],
 tasks:[...demoVisitors.map(v=>({id:v.id,title:v.action,due:'2026-10-29',priority:v.status==='Offre'?'Haute':'Normale',status:'À faire',property:v.property,contact:v.id,created:'2026-10-26T15:00:00'})),...searchSeedTasks()],
 buyerStatuses:Object.fromEntries(demoBuyerMatches.map(m=>[m.property,m.status])),
 contacts:[],documents:demoDocuments.map(d=>({...d})),proposals:[],tools:null,docTool:'gamma',calendar:{connected:false}
});
function searchSeedNotes(){return [{id:'note-search-lea',title:'Brief · Léa Martin',body:'Maison familiale avec jardin pour les enfants. Écoles à proximité appréciées. Accord bancaire en cours avec Antoine Vidal.',search:'lea-martin',contact:'lea',created:'2026-10-10T10:00:00'}];}
function searchSeedTasks(){return [{id:'task-search-lea',title:'Sélectionner deux nouveaux biens à Bruges',due:'2026-10-31',priority:'Normale',status:'À faire',search:'lea-martin',contact:'lea',created:'2026-10-20T09:00:00'}];}
const isRecordList=list=>Array.isArray(list)&&list.every(v=>v&&typeof v==='object'&&typeof v.id==='string');
function loadState(){try{const data=JSON.parse(localStorage.getItem(storageKey));if(data&&['visits','notes','tasks'].every(k=>isRecordList(data[k]))){const fresh=initialState();if(!data.visits.some(v=>v.id==='seller-proposed'))data.visits.push(fresh.visits.find(v=>v.id==='seller-proposed'));data.buyerStatuses={...fresh.buyerStatuses,...(data.buyerStatuses||{})};
 // Workspaces saved before the searches existed receive the search records once.
 if(!data.schema){data.notes.push(...searchSeedNotes());data.tasks.push(...searchSeedTasks());}
 for(const key of ['contacts','documents','proposals'])if(!isRecordList(data[key]))data[key]=fresh[key];
 if(!isRecordList(data.tools))data.tools=null;if(typeof data.docTool!=='string')data.docTool=fresh.docTool;if(!['pro','particulier'].includes(data.viewMode))data.viewMode='pro';if(!data.calendar||typeof data.calendar!=='object'||typeof data.calendar.connected!=='boolean')data.calendar={connected:false};data.schema=2;return data;}}catch{}return initialState();}
let state=loadState();let storageAvailable=true;
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state));storageAvailable=true;}catch{storageAvailable=false;}}
// Without authentication, the demo remembers which interface is being presented.
// A visitor of Li.La Particulier is kept out of the Hub and of every professional view.
function setViewMode(mode){if(['pro','particulier'].includes(mode)&&state.viewMode!==mode){state.viewMode=mode;save();}}
const notify=message=>{const el=$('save-status');if(el)el.textContent=message+(storageAvailable?'':' Le stockage du navigateur est indisponible ; cet ajout sera conservé jusqu’au rechargement.');};
const visits=id=>state.visits.filter(v=>v.property===id);
const dateLabel=value=>value?new Date(value+'T12:00:00').toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric'}):'Sans échéance';
const shortDate=value=>new Date(value+'T12:00:00').toLocaleDateString('fr-FR',{day:'numeric',month:'short'});
const visitDate=v=>dateLabel(v.date)+(v.time?' · '+v.time:'');
const dateBadge=value=>{const d=new Date(value+'T12:00:00');return `<span class="date-badge" aria-hidden="true"><strong>${d.getDate()}</strong><small>${esc(d.toLocaleDateString('fr-FR',{month:'short'}))}</small></span>`;};
const related=(item)=>[item.property&&mine(property(item.property))?link('bien/'+item.property,property(item.property).title):'',item.search&&searchFile(item.search)?link('recherche/'+item.search,searchFile(item.search).title):'',item.contact&&person(item.contact)?link('contact/'+item.contact,person(item.contact).name):''].filter(Boolean).join(' · ');
const photo=p=>p.photos?.length?`<img class="property-photo" src="${esc(p.photos[0])}" alt="Photo du bien ${esc(p.title)}">`:art(p);
const facts=p=>`${p.surface} m² · ${p.rooms} pièces · ${p.bedrooms} chambres`;
// Main photo first; the other photos are browsed from the thumbnails of the detailed view.
const galleryThumbs=p=>p.photos?.length>1?`<div class="gallery-thumbs" role="group" aria-label="Photos du bien">${p.photos.map((src,i)=>`<button type="button" class="${i?'':'active'}" data-gallery-src="${esc(src)}" aria-label="Afficher la photo ${i+1}"><img src="${esc(src)}" alt=""></button>`).join('')}</div>`:'';
function card(p,context='mine'){const own=mine(p),a=agent(p),route=propertyRoute(p);return `<article class="property-card"><a class="card-media" href="#/${route}" tabindex="-1" aria-hidden="true">${photo(p)}<span class="card-badges">${own?pill(p.status):''}${context==='hub'&&own?pill('Mon bien'):''}</span><span class="card-price">${money(p.price)}</span></a><div class="card-body"><small class="card-place">${icon('pin')}${esc(p.city)}</small><h2>${link(route,p.title)}</h2><p class="card-meta">${facts(p)}${p.land?' · '+p.land+' m² de terrain':''}</p>${context==='hub'&&!own?`<p class="agent-credit">Proposé par ${esc(a.name)}${a.agency?' – '+esc(a.agency):''}</p><div class="actions">${link(route,'Voir le bien','button primary')}<button data-agent="${esc(a.id)}" type="button">Contacter l’agent</button>${agentContact(a)?'':`<button type="button" class="icon-only" data-network-agent="${esc(a.id)}" aria-label="Ajouter ${esc(a.name)} à Mon Réseau" title="Ajouter l’agent à Mon Réseau">${icon('userPlus')}</button>`}</div>`:`<div class="actions">${link(route,'Ouvrir mon dossier','button primary')}${own&&context!=='hub'?`<small class="card-visits">${visits(p.id).length} visite(s)</small>`:''}</div>`}</div></article>`;}
function home(){
 const upcoming=state.visits.filter(v=>v.status==='Prévue').sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
 const open=state.tasks.filter(t=>t.status!=='Terminée').sort((a,b)=>(a.due||'9').localeCompare(b.due||'9'));
 const offers=state.visits.filter(v=>v.status==='Offre').length,published=demoProperties.filter(p=>p.published).length;
 const counts={hub:published+' biens publiés',biens:myProperties().length+' dossiers',recherches:demoSearches.length+' recherche active',reseau:allContacts().length+' contacts',notes:state.notes.length+' notes',taches:open.length+' à faire'};
 const media={hub:`<span class="bento-media mosaic">${demoProperties.filter(p=>p.published&&p.photos.length&&!mine(p)).map(p=>`<img src="${esc(p.photos[0])}" alt="">`).join('')}</span>`,biens:`<span class="bento-media"><img src="${esc(property('pessac').photos[0])}" alt=""></span>`,reseau:`<span class="avatar-stack">${allContacts().slice(0,4).map(avatar).join('')}</span>`};
 const today=new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'});
 return `<section class="hero"><img class="hero-bg" src="assets/maison-pessac.webp" alt=""><div class="hero-content"><p class="eyebrow">${esc(today)} · ${esc(demoLocation.city)} ${esc(demoLocation.temperature)} °C</p><h1>Bonjour, Camille.</h1><p class="hero-lead">${upcoming.length} visite${upcoming.length>1?'s':''} à venir, ${open.length} action${open.length>1?'s':''} à suivre et ${offers} offre${offers>1?'s':''} en cours.</p><div class="quick-actions" aria-label="Actions rapides">${[['contact','Ajouter un contact','userPlus'],['visit','Ajouter une visite','calendar'],['note','Ajouter une note','note'],['task','Ajouter une tâche','task']].map(([kind,label,ic])=>`<button type="button" class="qa" data-add="${kind}">${icon(ic)}<span>${label}</span></button>`).join('')}</div></div><dl class="hero-stats">${[['Visites à venir',upcoming.length],['Actions ouvertes',open.length],['Offres en cours',offers],['Biens publiés',published]].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl></section>
 <div class="bento">${sections.map(([id,name,ic,copy])=>`<a href="#/${id}" class="home-card bento-${id}${media[id]&&id!=='reseau'?' has-media':''}">${media[id]||''}<span class="home-icon">${icon(ic)}</span><span class="home-text"><strong>${name}</strong><small>${copy}</small></span><span class="home-count">${esc(counts[id])}${icon('arrow')}</span></a>`).join('')}</div>
 <div class="home-grid"><section class="panel agenda">${panelHead('Ma journée',link('journee','Ouvrir Ma journée','button small ghost'))}${state.calendar.connected?'':`<div class="calendar-cta"><p class="hint">Voyez vos rendez-vous personnels et professionnels à côté de vos visites.</p>${connectButton('small')}</div>`}${timeline(localToday(),{free:false})}<h3>Prochaines visites</h3>${upcoming.length?upcoming.slice(0,4).map(v=>`<button type="button" class="list-row" data-visitor="${esc(v.id)}">${dateBadge(v.date)}<span><strong>${esc(person(v.contact)?.name||v.name)}</strong><small>${esc(property(v.property)?.title||'')} · ${esc(v.time||'')}</small></span>${pill(v.sellerResponse||v.status)}</button>`).join(''):'<p class="empty">Aucune visite programmée.</p>'}</section>
 <section class="panel">${panelHead('À faire',link('taches','Toutes mes tâches','button small ghost'))}${open.length?open.slice(0,4).map(t=>`<div class="list-row task-row prio-${esc(norm(t.priority))}"><label class="check"><input type="checkbox" data-task="${esc(t.id)}"><span>${esc(t.title)}</span></label><small>${esc(t.due?shortDate(t.due):'')}</small></div>`).join(''):'<p class="empty">Rien à faire pour le moment.</p>'}</section></div>
 <section class="below">${panelHead('Dossiers en cours',link('biens','Voir tout','button small ghost'))}<div class="folio-row">${myProperties().filter(p=>!['Vendu','Retiré'].includes(p.status)).map(p=>`<a class="folio" href="#/bien/${esc(p.id)}"><span class="folio-media">${photo(p)}<span class="card-badges">${pill(p.status)}</span></span><span class="folio-body"><strong>${esc(p.title)}</strong><small>${money(p.price)} · ${visits(p.id).length} visite(s)</small></span></a>`).join('')}${demoSearches.map(s=>`<a class="folio" href="#/recherche/${esc(s.id)}"><span class="folio-media search-media">${searchProposals(s.id).slice(0,2).map(m=>photo(property(m.property))).join('')}<span class="card-badges">${pill(s.status)}</span></span><span class="folio-body"><strong>${esc(s.title)}</strong><small>${esc(s.type)} · ${money(s.budget)}</small></span></a>`).join('')}</div></section>`;
}
const banner=(eyebrow,title,copy,actions,photos)=>`<section class="page-banner">${photos?.length?`<div class="banner-photos">${photos.map(src=>`<img src="${esc(src)}" alt="">`).join('')}</div>`:''}<div class="banner-content"><p class="eyebrow">${esc(eyebrow)}</p><h1>${esc(title)}</h1><p>${esc(copy)}</p>${actions?`<div class="actions">${actions}</div>`:''}</div></section>`;
function hub(){return banner('Réservé aux professionnels Li.La','Hub Immobilier','Tous les biens publiés par les utilisateurs Li.La. Vos biens y figurent avec la mention « Mon bien ».',link('biens','Mes biens','button glass')+link('deposer','Déposer un bien','button primary'),demoProperties.filter(p=>p.published&&p.photos.length).map(p=>p.photos[0]))+`<div class="filters floating"><label>Rechercher<input id="hub-query" type="search" placeholder="Ville, titre…"></label><label>Type<select id="hub-type"><option value="">Tous les types</option><option>Maison</option><option>Appartement</option></select></label><label>Budget maximum<select id="hub-budget"><option value="">Tous les budgets</option><option value="300000">300 000 €</option><option value="400000">400 000 €</option><option value="500000">500 000 €</option><option value="600000">600 000 €</option></select></label></div><p id="hub-count" role="status" class="hint result-count"></p><div class="property-grid" id="hub-results"></div>`;}
const norm=s=>String(s).normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();
function filterHub(){const q=norm($('hub-query').value);const list=demoProperties.filter(p=>p.published&&norm(p.title+' '+p.city).includes(q)&&(!$('hub-type').value||p.type===$('hub-type').value)&&(!$('hub-budget').value||p.price<=Number($('hub-budget').value)));$('hub-count').textContent=`${list.length} bien(s)`;$('hub-results').innerHTML=list.length?list.map(p=>card(p,'hub')).join(''):'<div class="empty">Aucun bien ne correspond aux filtres.</div>';}
function myPropertiesView(){const list=myProperties();const statuses=[...new Set(list.map(p=>p.status))];return heading('Mes biens','Chaque bien est un dossier complet : propriétaire, mandat, visites, documents et synthèse.',link('deposer','Déposer un bien','button primary'),'Dossiers vendeurs')+`<div class="stat-strip">${[['Dossiers',list.length],['Publiés dans le Hub',list.filter(p=>p.published).length],['Visites',list.reduce((n,p)=>n+visits(p.id).length,0)],['Offres',list.reduce((n,p)=>n+visits(p.id).filter(v=>v.status==='Offre').length,0)]].map(([k,v])=>`<div><strong>${v}</strong><small>${k}</small></div>`).join('')}</div><p class="hint status-summary">${statuses.map(s=>`${list.filter(p=>p.status===s).length} ${esc(s.toLowerCase())}`).join(' · ')}</p><div class="property-grid">${list.map(p=>card(p)).join('')}</div>`;}
// Third-party listings expose only commercial fields and the agent's public contact.
function commercial(p){const a=agent(p);return `<div class="gallery-scope"><section class="cover commercial-cover"><div class="commercial-photos" data-gallery>${p.photos?.length?`<img src="${esc(p.photos[0])}" alt="Photo du bien ${esc(p.title)}">`:art(p)}</div><div class="cover-content"><p class="eyebrow">Fiche commerciale · ${esc(p.type)}</p><h1>${esc(p.title)}</h1><p class="cover-sub">${icon('pin')}${esc(p.city)} · ${facts(p)}</p><strong class="cover-price">${money(p.price)}</strong></div></section>${galleryThumbs(p)}</div><div class="cover-actions actions">${link('hub','Retour au Hub','button')}<button data-agent="${esc(a.id)}" class="primary" type="button">Contacter l’agent</button></div><div class="split"><section class="panel commercial-panel"><h2>Le bien</h2><p class="lead-copy">${esc(p.description)}</p><dl class="facts-grid">${[['Type',p.type],['Secteur',p.city],['Surface',p.surface+' m²'],['Pièces',p.rooms],['Chambres',p.bedrooms],['DPE',p.dpe],...(p.land?[['Terrain',p.land+' m²']]:[])].map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="chips">${p.features.map(f=>pill(f)).join('')}</div></section><aside class="panel agent-aside"><p class="eyebrow">Votre interlocuteur</p><div class="person-line"><span class="avatar t-rose" aria-hidden="true">${esc(initials(a.name))}</span><span><strong>${esc(a.name)}</strong><small>${esc(a.agency||'Agent indépendant')}</small></span></div><p>Proposé par ${esc(a.name)}${a.agency?' – '+esc(a.agency):''}</p><div class="actions stack"><button data-agent="${esc(a.id)}" class="primary" type="button">Contacter l’agent</button>${networkAgentButton(a)}</div></aside></div>`;}
const agentContact=a=>allContacts().find(c=>c.email&&c.email===a.email);
const networkAgentButton=a=>agentContact(a)?link('contact/'+agentContact(a).id,'Dans mon réseau','button'):`<button type="button" data-network-agent="${esc(a.id)}">${icon('userPlus')}Ajouter l’agent à Mon Réseau</button>`;
function agentPanel(id){const a=demoAgents.find(a=>a.id===id&&a.id!==currentAgentId);if(!a)return;showModal(`<p class="eyebrow">Agent Li.La</p><h2 id="detail-title">${esc(a.name)}</h2><dl><dt>Agence</dt><dd>${esc(a.agency||'Non renseignée')}</dd><dt>Téléphone</dt><dd>${esc(a.phone)}</dd><dt>E-mail</dt><dd>${esc(a.email)}</dd></dl><div class="actions">${contactLinks({phone:a.phone,email:a.email})}${networkAgentButton(a)}</div>`);}
function addAgentToNetwork(id){const a=demoAgents.find(a=>a.id===id&&a.id!==currentAgentId);if(!a||agentContact(a))return;state.contacts.push({id:'agent-'+a.id,name:a.name,company:a.agency||'Agent indépendant',job:'Agent immobilier',city:'Gironde',typology:'Collègue',phone:a.phone,email:a.email,properties:[],created:new Date().toISOString()});save();render();notify(a.name+' a été ajouté à Mon Réseau.');}
const noteKind=n=>n.property?['Bien','sand']:n.search?['Recherche','blue']:n.contact?['Contact','violet']:['Note libre','grey'];
function noteList(id,contact,search){const list=state.notes.filter(n=>(!id||n.property===id)&&(!contact||n.contact===contact)&&(!search||n.search===search));return list.length?list.map(n=>{const [kind,tone]=noteKind(n);return `<article class="record note kind-${tone}"><div class="note-meta">${pill(kind,tone)}${n.created?`<small>${esc(shortDate(n.created.slice(0,10)))}</small>`:''}</div><h3>${esc(n.title)}</h3><p class="user-copy">${esc(n.body)}</p><small class="note-links">${related(n)||'Note personnelle'}</small></article>`;}).join(''):'<p class="empty">Aucune note pour le moment.</p>';}
function taskList(id,contact,search,which){const list=state.tasks.filter(t=>(!id||t.property===id)&&(!contact||t.contact===contact)&&(!search||t.search===search)&&(!which||(which==='open')===(t.status!=='Terminée')));return list.length?list.map(t=>`<article class="record task prio-${esc(norm(t.priority))}"><label class="check"><input type="checkbox" data-task="${esc(t.id)}" ${t.status==='Terminée'?'checked':''}><span>${esc(t.title)}</span></label><div class="task-meta">${pill(t.priority)}${pill(t.status)}<small>${icon('clock')}Échéance : ${esc(dateLabel(t.due))}</small></div><small>${related(t)||'Tâche personnelle'}</small></article>`).join(''):`<p class="empty">${which==='done'?'Aucune tâche terminée.':'Aucune action planifiée.'}</p>`;}
const docExt=name=>(String(name).match(/\.([a-z0-9]{2,4})$/i)?.[1]||'doc').toLowerCase();
function documentList(filter){const list=state.documents.filter(d=>(!filter.property||d.property===filter.property)&&(!filter.search||d.search===filter.search)&&(!filter.shared||d.shared)).sort((a,b)=>b.date.localeCompare(a.date));return list.length?`<div class="doc-list">${list.map(d=>`<div class="doc-tile"><span class="doc-ext ext-${esc(docExt(d.name))}">${esc(docExt(d.name).toUpperCase())}</span><span class="doc-name"><strong>${esc(d.name)}</strong><small>${esc(d.type)} · ${esc(dateLabel(d.date))}</small></span>${d.shared&&!filter.shared?`<span class="doc-shared" title="Visible dans l’espace du client">${icon('eye')}Partagé</span>`:''}</div>`).join('')}</div>`:'<p class="empty">Aucun document.</p>';}
const jumpNav=items=>`<nav class="section-nav" aria-label="Sections du dossier">${items.map(([id,label,count])=>`<button type="button" data-jump="${id}">${esc(label)}${count!=null?`<span>${count}</span>`:''}</button>`).join('')}</nav>`;
const splitName=name=>{const parts=String(name||'').split(/\s+/);return [parts[0]||'',parts.slice(1).join(' ')];};
function ownerCard(p){const c=person('owner-'+p.id);if(!c)return '';const [first,last]=splitName(c.name);const email=c.email||c.id+'@example.com';return `<section class="panel private-card"><p class="private-flag">${icon('lock')}Informations privées — non diffusées dans le Hub</p><h2>Propriétaire</h2><div class="person-line">${avatar(c)}<span><strong>${link('contact/'+c.id,c.name)}</strong><small>${esc([c.job,c.city].filter(Boolean).join(' · '))}</small></span></div><dl><dt>Prénom</dt><dd>${esc(first)}</dd><dt>Nom</dt><dd>${esc(last)}</dd><dt>Téléphone</dt><dd>${esc(c.phone||'Non renseigné')}</dd><dt>E-mail</dt><dd>${esc(email)}</dd><dt>Espace Li.La Particulier</dt><dd>${p.id===sellerPropertyId?'Accès vendeur actif':'Non activé'}</dd></dl><div class="actions">${contactLinks({phone:c.phone,email})}</div></section>`;}
function mandateCard(p){return `<section class="panel mandate-card"><p class="private-flag">${icon('shield')}Dossier interne</p><h2>Mandat</h2><div class="mandate-type"><span>${icon('key')}</span><strong>${esc(p.mandate||'À renseigner')}</strong></div><dl><dt>Référence</dt><dd>${esc(p.mandateRef||'—')}</dd><dt>Signé le</dt><dd>${esc(p.mandateDate?dateLabel(p.mandateDate):'—')}</dd><dt>Hub Immobilier</dt><dd>${p.published?'Publié':'Non publié'}</dd></dl></section>`;}
function dossier(p){const list=visits(p.id);const ids=[...new Set(['owner-'+p.id,...list.map(v=>v.contact),...state.notes.filter(n=>n.property===p.id).map(n=>n.contact),...state.tasks.filter(t=>t.property===p.id).map(t=>t.contact)])].filter(id=>person(id));const notesCount=state.notes.filter(n=>n.property===p.id).length,tasksCount=state.tasks.filter(t=>t.property===p.id).length,docsCount=state.documents.filter(d=>d.property===p.id).length;const next=list.filter(v=>v.status==='Prévue').sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))[0];
 return `<div class="gallery-scope"><section class="cover"><div class="dossier-media" data-gallery>${photo(p)}</div><div class="cover-content"><p class="eyebrow">Dossier vendeur</p><div class="chips">${pill(p.status)}${p.published?'<span class="pill t-glass">Visible dans le Hub</span>':''}${p.mandate?`<span class="pill t-glass">Mandat ${esc(p.mandate.toLowerCase())}</span>`:''}</div><h1>${esc(p.title)}</h1><p class="cover-sub">${icon('pin')}${esc(p.city)} · ${facts(p)}${p.land?' · Terrain '+p.land+' m²':''}</p><strong class="cover-price">${money(p.price)}</strong></div></section>${galleryThumbs(p)}</div>
 <div class="cover-actions actions">${link('biens','Mes biens','button')}${button('visit','+ Ajouter une visite',p.id)}${button('note','+ Ajouter une note',p.id)}${button('task','+ Ajouter une tâche / action',p.id)}<button type="button" data-synthesis-scroll>${icon('sparkle')}Synthèse du dossier</button></div>
 <div class="kpi-strip"><div><small>Visites</small><strong>${list.length}</strong></div><div><small>Contre-visites</small><strong>${list.filter(v=>v.status==='Contre-visite').length}</strong></div><div><small>Offres reçues</small><strong>${list.filter(v=>v.status==='Offre').length}</strong></div><div><small>Documents</small><strong>${docsCount}</strong></div><div><small>Prochaine visite</small><strong class="kpi-date">${next?esc(shortDate(next.date)+' · '+next.time):'—'}</strong></div></div>
 <div class="dossier-layout"><div class="dossier-main">${jumpNav([['sec-visites','Visites',list.length],['sec-notes','Notes',notesCount],['sec-taches','Tâches',tasksCount],['sec-documents','Documents',docsCount],['sec-contacts','Contacts',ids.length],['sec-historique','Historique'],['synthesis-panel','Synthèse']])}
 <details class="panel property-summary" open><summary>Informations du bien</summary><p class="lead-copy">${esc(p.description)}</p><dl class="facts-grid">${[['Type',p.type],['Surface',p.surface+' m²'],['Pièces',p.rooms],['Chambres',p.bedrooms],...(p.land?[['Terrain',p.land+' m²']]:[]),['DPE',p.dpe],...(p.listedOn?[['Mise en vente',dateLabel(p.listedOn)]]:[])].map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="chips">${p.features.map(f=>pill(f)).join('')}</div></details>
 <section class="panel below">${panelHead('Visites & visiteurs',button('visit','Nouvelle visite',p.id).replace('class="primary"','class="small"'),'sec-visites')}${list.length?`<div class="visit-list">${list.map(v=>`<button class="visit-row" data-visitor="${esc(v.id)}">${dateBadge(v.date)}<span><strong>${esc(person(v.contact)?.name||v.name)}</strong><small>${esc(visitDate(v))}</small></span>${pill(v.status)}<span>${v.sellerResponse?'Réponse vendeur : '+esc(v.sellerResponse):v.offer?money(v.offer):'Voir le suivi →'}</span></button>`).join('')}</div>`:'<p class="empty">Aucune visite programmée.</p>'}</section>
 <div class="split even below"><section class="panel">${panelHead('Notes du dossier','','sec-notes')}${noteList(p.id)}</section><section class="panel">${panelHead('Prochaines actions','','sec-taches')}${taskList(p.id)}</section></div>
 <section class="panel below">${panelHead('Documents',addButton('document','+ Ajouter un document',{property:p.id},'small'),'sec-documents')}${documentList({property:p.id})}<p class="hint">Stockage local : seuls le nom, la catégorie et la date sont conservés.</p></section>
 <section class="panel below">${panelHead('Historique','','sec-historique')}${history({property:p.id})}</section></div>
 <aside class="dossier-aside">${ownerCard(p)}${mandateCard(p)}<section class="panel">${panelHead('Contacts liés','','sec-contacts')}<div class="people">${ids.map(id=>personLine(person(id))).join('')}</div></section></aside></div>`;}
const personLine=c=>`<a class="person-line" href="#/contact/${esc(c.id)}">${avatar(c)}<span><strong>${esc(c.name)}</strong><small>${esc([c.trade||c.job,c.city].filter(Boolean).join(' · '))}</small></span>${pill(c.typology)}</a>`;
function history(filter){const match=item=>Object.entries(filter).every(([k,v])=>item[k]===v);const visitMatch=v=>filter.property?v.property===filter.property:filter.contact?v.contact===filter.contact:false;const events=[...state.visits.filter(visitMatch).map(v=>({date:v.date+'T'+(v.time||'12:00'),text:'Visite · '+(person(v.contact)?.name||v.name)+' · '+(property(v.property)?.title||'')+' · '+v.status})),...state.notes.filter(match).map(n=>({date:n.created,text:'Note ajoutée · '+n.title})),...state.tasks.filter(match).map(t=>({date:t.created,text:'Action ajoutée · '+t.title})),...state.documents.filter(d=>(filter.property&&d.property===filter.property)||(filter.search&&d.search===filter.search)).map(d=>({date:d.date+'T09:00',text:'Document ajouté · '+d.name})),...(filter.search?searchProposals(filter.search).map(m=>({date:(m.proposedOn||m.created||'').slice(0,10)+'T08:00',text:'Bien proposé · '+(property(m.property)?.title||'')})):[])].filter(e=>e.date).sort((a,b)=>b.date.localeCompare(a.date));const item=e=>`<li><small>${esc(dateLabel(e.date.slice(0,10)))}</small><p>${esc(e.text)}</p></li>`;return events.length?`<ol class="timeline">${events.slice(0,8).map(item).join('')}</ol>${events.length>8?`<details class="more"><summary>Voir tout l’historique (${events.length})</summary><ol class="timeline">${events.slice(8).map(item).join('')}</ol></details>`:''}`:'<p>Ouverture du dossier.</p>';}
function notes(id){const list=state.notes.filter(n=>!id||n.property===id);return heading('Mes Notes',id?property(id).title:'Vos notes libres et vos comptes rendus, liés à un bien, un contact ou une recherche.',(id?link('bien/'+id,'Retour au bien','button'):'')+button('note','+ Ajouter une note',id||''),'Carnet')+`<div class="stat-strip compact">${[['Toutes',list.length],['Biens',list.filter(n=>n.property).length],['Recherches',list.filter(n=>n.search).length],['Libres',list.filter(n=>!n.property&&!n.search&&!n.contact).length]].map(([k,v])=>`<div><strong>${v}</strong><small>${k}</small></div>`).join('')}</div><div class="note-grid">${noteList(id)}</div>`;}
function tasks(id){const open=state.tasks.filter(t=>(!id||t.property===id)&&t.status!=='Terminée');return heading('Mes Tâches',id?property(id).title:'Vos prochaines actions, par priorité et échéance.',(id?link('bien/'+id,'Retour au bien','button'):'')+button('task','+ Ajouter une tâche',id||''),'Organisation')+`<div class="stat-strip compact">${[['À faire',open.filter(t=>t.status==='À faire').length],['En cours',open.filter(t=>t.status==='En cours').length],['Priorité haute',open.filter(t=>t.priority==='Haute').length],['Terminées',state.tasks.filter(t=>(!id||t.property===id)&&t.status==='Terminée').length]].map(([k,v])=>`<div><strong>${v}</strong><small>${k}</small></div>`).join('')}</div><div class="task-board"><section class="panel"><h2>À traiter</h2>${taskList(id,null,null,'open')}</section><section class="panel done-panel"><h2>Terminées</h2>${taskList(id,null,null,'done')}</section></div>`;}
const phoneHref=phone=>'tel:'+String(phone).replace(/[^\d+]/g,'');
const whatsappHref=phone=>{const digits=String(phone).replace(/\D/g,'');return 'https://wa.me/'+(digits.startsWith('0')?'33'+digits.slice(1):digits);};
const contactLinks=c=>(c.phone?`<a class="button" href="${esc(phoneHref(c.phone))}">${icon('phone')}Appeler</a>`:'')+(c.email?`<a class="button" href="mailto:${esc(c.email)}">${icon('mail')}Email</a>`:'')+(c.phone?`<a class="button" href="${esc(whatsappHref(c.phone))}" target="_blank" rel="noopener noreferrer">${icon('chat')}WhatsApp</a>`:'');
function contact(id){const c=person(id);if(!c)return missing();const email=c.email||c.id+'@example.com';const properties=[...new Set([...(c.properties||[]),...state.visits.filter(v=>v.contact===id).map(v=>v.property),...state.notes.filter(n=>n.contact===id).map(n=>n.property),...state.tasks.filter(t=>t.contact===id).map(t=>t.property)])].filter(id=>mine(property(id)));const searches=demoSearches.filter(s=>s.contacts.includes(id)||state.notes.some(n=>n.contact===id&&n.search===s.id));
 return `<section class="contact-cover">${avatar(c)}<div class="contact-id"><p class="eyebrow">Fiche contact</p><h1>${esc(c.name)}</h1><p>${esc([c.job,c.company].filter(Boolean).join(' · '))}</p><div class="chips">${pill(c.typology)}${c.trade?pill(c.trade,'slate'):''}<small class="card-place">${icon('pin')}${esc(c.city||'Localité non renseignée')}</small></div></div></section>
 <section class="panel contact-hero"><div class="actions contact-actions">${contactLinks({phone:c.phone,email})}${addButton('note','+ Note',{contact:id},'small')}${addButton('task','+ Tâche',{contact:id},'small')}${link('reseau','Mon Réseau','button small ghost')}</div></section>
 <div class="split below"><section class="panel"><h2>Coordonnées</h2><dl>${[['Société',c.company||'—'],['Métier',c.job||'—'],['Ville',c.city||'—'],['Typologie',c.typology],...(c.trade?[['Métier professionnel',c.trade]]:[]),['E-mail',email],['Téléphone',c.phone||'Non renseigné']].map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl><h3>Biens liés</h3>${properties.length?`<div class="folio-row compact">${properties.map(pid=>`<a class="folio" href="#/bien/${esc(pid)}"><span class="folio-media">${photo(property(pid))}</span><span class="folio-body"><strong>${esc(property(pid).title)}</strong><small>${money(property(pid).price)}</small></span></a>`).join('')}</div>`:'<p class="hint">Aucun bien lié.</p>'}<h3>Recherches liées</h3>${searches.length?searches.map(s=>`<p>${link('recherche/'+s.id,s.title,'button')}</p>`).join(''):'<p class="hint">Aucune recherche liée.</p>'}</section><section class="panel"><h2>Notes</h2>${noteList(null,id)}<h2 class="spaced">Prochaines actions</h2>${taskList(null,id)}</section></div>
 <section class="panel below"><h2>Historique</h2>${history({contact:id})}</section>`;}
function visitor(id){const v=state.visits.find(v=>v.id===id);if(!v)return;showModal(`<p class="eyebrow">Suivi de visite</p><h2 id="detail-title">${esc(person(v.contact)?.name||v.name)}</h2><p>${esc(property(v.property).title)} · ${esc(visitDate(v))}</p>${pill(v.status)}${v.sellerResponse?`<p>Réponse du vendeur : <strong>${esc(v.sellerResponse)}</strong></p>`:''}<h3>Commentaire</h3><p class="user-copy">${esc(v.comment||'Aucun commentaire.')}</p>${v.calendar?`<p>Google Agenda : <strong>${v.calendar==='Ajoutée'?'visite ajoutée (simulation)':'ajout en attente de connexion'}</strong></p>`:''}${v.action?`<h3>Prochaine action</h3><p class="user-copy">${esc(v.action)}</p>`:''}${v.offer?`<p>Offre : ${money(v.offer)}</p>`:''}<div class="actions">${link('contact/'+v.contact,'Fiche contact','button primary')}${link('notes/'+v.property,'Notes du bien','button')}${link('taches/'+v.property,'Tâches du bien','button')}</div>`);}
function showModal(html){$('detail-body').innerHTML=html;if(!$('detail').open)$('detail').showModal();}
function missing(){return heading('Page introuvable','Cette page n’existe pas.',link('accueil','Retour à l’accueil','button'));}
function proRestricted(){return `<section class="restricted"><span class="restricted-icon">${icon('lock')}</span><p class="eyebrow">Li.La Particulier</p><h1>Espace réservé aux professionnels</h1><p>Le Hub Immobilier et les dossiers professionnels ne sont pas accessibles depuis votre espace particulier.</p><div class="actions">${link('particulier','Mon bien','button primary')}${link('particulier/recherche','Ma recherche','button')}${link('particulier/bienvenue','Accueil','button')}</div></section>`;}
const options=(values,all='Tous')=>`<option value="">${all}</option>`+values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');
function network(){return heading('Mon Réseau','Votre carnet professionnel : clients, partenaires et confrères.',addButton('contact','+ Ajouter un contact'),'Carnet d’adresses')+`<div class="typology-chips" role="group" aria-label="Filtrer par typologie"><button type="button" data-typology-chip="" class="chip active">Tous</button>${contactTypologies.map(t=>`<button type="button" data-typology-chip="${esc(t)}" class="chip"><span class="dot t-${tones[t]}"></span>${esc(t)}</button>`).join('')}</div><div class="filters network-filters"><label>Rechercher<input id="network-query" type="search" placeholder="Nom, société, métier, ville…"></label><label>Localité<select id="network-city">${options([...new Set(allContacts().map(c=>c.city).filter(Boolean))].sort(),'Toutes les localités')}</select></label><label>Typologie<select id="network-typology">${options(contactTypologies,'Toutes les typologies')}</select></label><label>Métier professionnel<select id="network-trade">${options(professionalTrades,'Tous les métiers pro')}</select></label><label>Profession<select id="network-job">${options([...new Set(allContacts().map(c=>c.job).filter(Boolean))].sort(),'Toutes les professions')}</select></label></div><p id="network-count" class="hint result-count" role="status"></p><div id="network-results" class="record-grid"></div>`;}
function filterNetwork(){const q=norm($('network-query').value.trim());const list=allContacts().filter(c=>norm([c.name,c.company,c.job,c.city,c.trade].join(' ')).includes(q)&&['city','typology','trade','job'].every(k=>!$('network-'+k).value||c[k]===$('network-'+k).value));document.querySelectorAll('[data-typology-chip]').forEach(b=>b.classList.toggle('active',b.dataset.typologyChip===$('network-typology').value));$('network-count').textContent=`${list.length} contact(s)`;$('network-results').innerHTML=list.length?list.map(c=>`<article class="panel contact-card"><div class="person-line">${avatar(c)}<span><strong>${esc(c.name)}</strong><small>${esc([c.company,c.job].filter(Boolean).join(' · '))}</small></span></div><div class="chips">${pill(c.typology)}${c.trade?pill(c.trade,'slate'):''}<small class="card-place">${icon('pin')}${esc(c.city||'')}</small></div><div class="actions">${link('contact/'+c.id,'Fiche contact','button small')}${c.phone?`<a class="button small icon-only" href="${esc(phoneHref(c.phone))}" aria-label="Appeler ${esc(c.name)}">${icon('phone')}</a>`:''}<a class="button small icon-only" href="mailto:${esc(c.email||c.id+'@example.com')}" aria-label="Écrire à ${esc(c.name)}">${icon('mail')}</a></div></article>`).join(''):'<p class="empty">Aucun contact ne correspond aux filtres.</p>';}
// Additions are stored only in this browser, under the demo-specific key.
function relationSelect(name,label,list,value='',required=false){return `<label>${label}<select name="${name}" ${required?'required':''}><option value="">${required?'Sélectionner…':'Aucun'}</option>${list.map(item=>`<option value="${esc(item.id)}" ${item.id===value?'selected':''}>${esc(item.name||item.title)}</option>`).join('')}</select></label>`;}
const localToday=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
function quickAdd(){showModal(`<p class="eyebrow">Ajout rapide</p><h2 id="detail-title">Que voulez-vous ajouter ?</h2><div class="qa-grid">${[['contact','+ Ajouter un contact','userPlus'],['visit','+ Ajouter une visite','calendar'],['note','+ Ajouter une note','note'],['task','+ Ajouter une tâche','task']].map(([kind,label,ic])=>`<button type="button" class="qa" data-add="${kind}">${icon(ic)}<span>${label}</span></button>`).join('')}</div>`);}
function addDialog(kind,ctx={}){
 const titles={visit:'Ajouter une visite',note:'Ajouter une note',task:'Ajouter une tâche',contact:'Ajouter un contact',document:'Ajouter un document',proposal:'Ajouter un bien proposé'};
 const today=localToday();
 const relations=relationSelect('property','Bien lié'+(kind==='visit'?'':' (facultatif)'),myProperties(),ctx.property,kind==='visit')+relationSelect('contact',kind==='visit'?'Visiteur / contact':'Contact lié (facultatif)',allContacts(),ctx.contact,kind==='visit')+(kind==='visit'?'':relationSelect('search','Recherche liée (facultatif)',demoSearches,ctx.search));
 let fields;
 if(kind==='visit')fields=`<div class="form-grid">${input('date','Date','date',today,'required')}${input('time','Heure','time','10:00','required')}${relations}${select('status','Statut',visitStatuses)}</div><label>Commentaire<textarea name="comment" rows="4" maxlength="5000"></textarea></label><label class="check calendar-option"><input type="checkbox" name="addToCalendar" ${state.calendar.connected?'checked':''}><span>Ajouter également à mon Google Agenda</span></label><p class="hint">${state.calendar.connected?'La visite reste enregistrée dans Li.La et une copie est ajoutée à votre agenda (simulation).':'Google Agenda n’est pas connecté : l’ajout sera fait dès la connexion. La visite reste enregistrée dans Li.La.'}</p>${input('nextAction','Prochaine action (facultatif, ajoutée aux tâches du dossier)','text','','maxlength="160" placeholder="Rappeler, envoyer les diagnostics…"')}`;
 else if(kind==='note')fields=`${input('title','Titre','text','','required maxlength="160"')}<label>Note<textarea name="body" rows="5" required maxlength="10000"></textarea></label><div class="form-grid">${relations}</div>`;
 else if(kind==='task')fields=`${input('title','Intitulé','text','','required maxlength="160"')}<div class="form-grid">${input('due','Échéance','date','','required')}${select('priority','Priorité',priorities)}${select('status','Statut',taskStatuses)}${relations}</div>`;
 else if(kind==='contact')fields=`<div class="form-grid">${input('name','Nom et prénom','text','','required maxlength="120"')}${select('typology','Typologie',contactTypologies)}<label data-trade hidden>Métier professionnel<select name="trade">${professionalTrades.map(o=>`<option>${o}</option>`).join('')}</select></label>${input('company','Société','text','','maxlength="120"')}${input('job','Profession','text','','maxlength="80"')}${input('city','Ville','text','','maxlength="80"')}${input('phone','Téléphone','tel','','maxlength="30"')}${input('email','E-mail','email','','maxlength="160"')}</div>`;
 else if(kind==='document')fields=`<label>Fichier (facultatif, seul le nom est repris)<input name="file" type="file"></label>${input('name','Nom du document','text','','required maxlength="160"')}<div class="form-grid">${select('type','Catégorie',documentTypes)}${ctx.property||ctx.search?'':relationSelect('property','Bien lié (facultatif)',myProperties())+relationSelect('search','Recherche liée (facultatif)',demoSearches)}</div><label class="check"><input type="checkbox" name="shared">Partager avec le client (visible dans son espace Li.La Particulier)</label>${ctx.property?`<input type="hidden" name="property" value="${esc(ctx.property)}">`:''}${ctx.search?`<input type="hidden" name="search" value="${esc(ctx.search)}">`:''}`;
 else {const taken=new Set(searchProposals(ctx.search).map(m=>m.property));fields=`<input type="hidden" name="search" value="${esc(ctx.search)}">${relationSelect('property','Bien à proposer',demoProperties.filter(p=>(p.published||mine(p))&&!['Vendu','Retiré'].includes(p.status)&&!taken.has(p.id)),'',true)}<label>Message pour l’acquéreur (facultatif)<textarea name="comment" rows="3" maxlength="1000"></textarea></label>`;}
 showModal(`<p class="eyebrow">Li.La</p><h2 id="detail-title">${titles[kind]}</h2><form id="add-form" data-kind="${kind}" class="editor-form">${fields}<p class="hint">Enregistré uniquement dans ce navigateur.</p><p id="add-error" role="alert"></p><div class="actions"><button type="submit" class="primary">Ajouter</button><button type="button" data-cancel>Annuler</button></div></form>`);
 const form=$('add-form');form.addEventListener('submit',saveAddition);
 if(kind==='contact'){const sync=()=>{const pro=form.elements.typology.value==='Professionnel';form.querySelector('[data-trade]').hidden=!pro;form.elements.trade.disabled=!pro;};form.elements.typology.addEventListener('change',sync);sync();}
 if(kind==='document')form.elements.file.addEventListener('change',()=>{const file=form.elements.file.files[0];if(file&&!form.elements.name.value)form.elements.name.value=file.name.slice(0,160);});
}
function saveAddition(event){
 event.preventDefault();const form=event.target;const data=Object.fromEntries([...new FormData(form)].filter(([,v])=>typeof v==='string'));const kind=form.dataset.kind;
 const fail=message=>{$('add-error').textContent=message;};
 if((data.property&&!(mine(property(data.property))||(kind==='proposal'&&property(data.property)?.published)))||(data.contact&&!person(data.contact))||(data.search&&!searchFile(data.search)))return fail('Sélectionnez un de vos biens et un contact valides.');
 if(['note','task','document'].includes(kind)&&(!(data.title??data.name)?.trim()||(kind==='note'&&!data.body?.trim())))return fail('Complétez les champs avant d’ajouter cet élément.');
 const item={...data,id:crypto.randomUUID(),created:new Date().toISOString()};let message;
 if(kind==='visit'){
  if(!data.property||!data.contact||!data.date||!data.time||!visitStatuses.includes(data.status))return;
  const action=(data.nextAction||'').trim();delete item.nextAction;const toCalendar=data.addToCalendar==='on';delete item.addToCalendar;
  state.visits.unshift({...item,name:person(data.contact).name,comment:data.comment.trim(),offer:null,...(action?{action}:{}),...(toCalendar?{calendar:state.calendar.connected?'Ajoutée':'En attente'}:{})});
  // One entry feeds the whole dossier: the next action becomes a linked task.
  if(action)state.tasks.unshift({id:crypto.randomUUID(),title:action,due:data.date,priority:'Normale',status:'À faire',property:data.property,contact:data.contact,created:item.created});
  message=(action?'Visite et prochaine action ajoutées.':'Visite ajoutée.')+(toCalendar?(state.calendar.connected?' Ajoutée également à Google Agenda (simulation).':' Ajout à Google Agenda en attente de connexion.'):'');
 }else if(kind==='note'){state.notes.unshift({...item,title:data.title.trim(),body:data.body.trim()});message='Note ajoutée.';}
 else if(kind==='task'){if(!taskStatuses.includes(data.status)||!priorities.includes(data.priority))return;state.tasks.unshift({...item,title:data.title.trim()});message='Tâche ajoutée.';}
 else if(kind==='contact'){if(!data.name?.trim()||!contactTypologies.includes(data.typology)||(data.trade&&!professionalTrades.includes(data.trade)))return fail('Indiquez au moins un nom et une typologie.');const c={id:'local-'+item.id,name:data.name.trim(),typology:data.typology,company:data.company.trim(),job:data.job.trim(),city:data.city.trim(),phone:data.phone.trim(),email:data.email.trim(),properties:[],created:item.created};if(data.typology==='Professionnel')c.trade=data.trade;state.contacts.push(c);message='Contact ajouté à Mon Réseau.';}
 else if(kind==='document'){if(!documentTypes.includes(data.type))return;state.documents.unshift({id:item.id,name:data.name.trim(),type:data.type,date:localToday(),...(data.shared?{shared:true}:{}),...(data.property?{property:data.property}:{}),...(data.search?{search:data.search}:{})});message='Document ajouté.';}
 else {if(!data.search||!data.property||searchProposals(data.search).some(m=>m.property===data.property))return fail('Sélectionnez un bien à proposer.');state.proposals.push({id:item.id,search:data.search,property:data.property,status:'À découvrir',comment:data.comment.trim(),proposedOn:localToday()});state.buyerStatuses[data.property]='À découvrir';message='Bien proposé à l’acquéreur.';}
 save();render();notify(message);
}
const input=(name,label,type='text',value='',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(name,label,options,extra='')=>`<label>${label}<select name="${name}" ${extra}>${options.map(o=>`<option>${o}</option>`).join('')}</select></label>`;
const checks=(name,options)=>`<div class="checks">${options.map(o=>`<label class="check"><input type="checkbox" name="${name}" value="${o}">${o}</label>`).join('')}</div>`;
let photoUrls=[];
// Professional deposit photos: several images, reorderable, the first one is the main photo. Local object URLs only.
let depositPhotos=[];const maxDepositPhotos=10;
// The field list is kept as is pending the comparison with the original professional form.
function deposit(){return heading('Déposer un bien','Les informations de votre bien. Un bien publié dans le Hub dispose d’un mandat.',link('hub','Retour au Hub','button'),'Nouveau dossier')+`<form id="deposit-form"><fieldset><legend>01 · Le bien</legend><div class="form-grid">${input('title','Titre du bien','text','Maison Pessac','required maxlength="120"')}${select('transaction','Transaction',['Vente','Location'])}${select('type','Type de bien',['Maison','Appartement','Terrain','Immeuble','Local commercial','Autre'])}${select('usage','Usage du bien',['Résidence principale','Résidence secondaire','Locatif','Succession','Autre'])}${input('city','Ville','text','Pessac','required')}${input('address','Adresse','text','','placeholder="Numéro et rue"')}</div></fieldset><fieldset><legend>02 · Surfaces et caractéristiques</legend><div class="form-grid">${input('surface','Surface (m²)','number',125,'required min="1"')}${input('rooms','Nombre de pièces','number',5,'min="0"')}${input('bedrooms','Chambres','number',4,'min="0"')}<div data-condition="house">${input('land','Surface du terrain (m²)','number',640,'min="0"')}</div><div data-condition="apartment" hidden>${input('floor','Étage','number',1)}${select('lift','Ascenseur',['Oui','Non'])}</div>${select('condition','État général',['Bon','Excellent','À rafraîchir','Travaux importants'])}${input('year','Année de construction','number',1998,'min="1600" max="2100"')}</div><p>Équipements et extérieurs</p>${checks('features',['Cuisine équipée','Double vitrage','Climatisation','Cave','Balcon','Terrasse','Jardin','Piscine','Stationnement','Garage'])}</fieldset><fieldset><legend>03 · Situation et commercialisation</legend><div class="form-grid">${select('occupation','Occupation',['Libre','Occupé par le propriétaire','Loué'])}${select('diagnostics','Diagnostics',['Réalisés','Programmés','Non réalisés'])}${select('dpe','DPE',['C','A','B','D','E','F','G','Non renseigné'])}${select('mandate','Mandat (obligatoire pour publier)',['Exclusif','Simple'],'required')}<div data-condition="sale">${input('price','Prix souhaité (€)','number',465000,'required min="1"')}</div><div data-condition="rent" hidden>${input('rent','Loyer mensuel (€)','number','','min="1"')}${input('charges','Charges mensuelles (€)','number','','min="0"')}${select('rentalType','Type de location',['Vide','Meublée'])}</div></div><label>Description et travaux à prévoir<textarea name="description" rows="3" placeholder="Décrivez le bien…">Maison lumineuse avec jardin et terrasse.</textarea></label></fieldset><fieldset class="private-fieldset"><legend>04 · Propriétaire et disponibilités</legend><p class="private-flag">${icon('lock')}Informations privées — non diffusées dans le Hub</p><div class="form-grid">${input('ownerFirstName','Prénom du propriétaire','text','Claire','required maxlength="60"')}${input('owner','Nom du propriétaire','text','Morel','required maxlength="80"')}${input('ownerPhone','Téléphone','tel','06 10 20 30 11','maxlength="30"')}${input('email','E-mail','email','claire@example.com')}${input('availability','Disponibilités pour les visites','text','Sur rendez-vous')}${select('preferred','Contact préféré',['E-mail','Téléphone','Indifférent'])}</div></fieldset><fieldset><legend>05 · Photos et prévisualisation</legend><label class="photo-drop">${icon('camera')}<span><strong>Ajouter des photos</strong><small>Plusieurs images possibles · la première est la photo principale</small></span><input id="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><p class="hint">${maxDepositPhotos} images maximum, 5 Mo par image. Aucune photo n’est envoyée.</p><p id="photo-status" role="status"></p><div id="photo-preview" class="photo-gallery"></div><button class="primary" type="submit">Prévisualiser le bien</button></fieldset></form>`;}
function conditions(){const f=$('deposit-form');const type=f.elements.type.value;const rental=f.elements.transaction.value==='Location';for(const [name,visible] of Object.entries({house:['Maison','Terrain'].includes(type),apartment:type==='Appartement',sale:!rental,rent:rental})){const group=f.querySelector(`[data-condition="${name}"]`);group.hidden=!visible;group.querySelectorAll('input,select').forEach(el=>el.disabled=!visible);}f.elements.rent.required=rental;}
function renderDepositPhotos(){$('photo-preview').innerHTML=depositPhotos.map((ph,i)=>`<figure class="photo-tile${i?'':' is-main'}"><img src="${ph.url}" alt="Photo ${i+1} sélectionnée : ${esc(ph.name)}"><figcaption>${i?'Photo '+(i+1):`${icon('star')}Photo principale`}</figcaption><div class="photo-tools"><button type="button" data-photo-op="left" data-photo-index="${i}" aria-label="Déplacer la photo ${i+1} vers la gauche" ${i?'':'disabled'}>${icon('left')}</button><button type="button" data-photo-op="main" data-photo-index="${i}" aria-label="Définir la photo ${i+1} comme photo principale" ${i?'':'disabled'}>${icon('star')}</button><button type="button" data-photo-op="right" data-photo-index="${i}" aria-label="Déplacer la photo ${i+1} vers la droite" ${i<depositPhotos.length-1?'':'disabled'}>${icon('right')}</button><button type="button" data-photo-op="remove" data-photo-index="${i}" aria-label="Retirer la photo ${i+1}">${icon('x')}</button></div></figure>`).join('');}
function photoOperation(op,i){const list=depositPhotos;if(!list[i])return;if(op==='remove'){URL.revokeObjectURL(list[i].url);list.splice(i,1);}else if(op==='main')list.unshift(...list.splice(i,1));else{const j=op==='left'?i-1:i+1;if(!list[j])return;[list[i],list[j]]=[list[j],list[i]];}renderDepositPhotos();$('photo-status').textContent=`${list.length} photo(s) · photo principale : ${list[0]?.name||'aucune'}.`;}
function preview(event){event.preventDefault();const data=new FormData(event.target);const rows=[['Projet',data.get('transaction')],['Type',data.get('type')],['Usage',data.get('usage')],['Ville',data.get('city')],['Adresse',data.get('address')],['Surface',data.get('surface')+' m²'],['Pièces / chambres',data.get('rooms')+' / '+data.get('bedrooms')],['Terrain',data.get('land')?data.get('land')+' m²':''],['Étage',data.get('floor')],['Ascenseur',data.get('lift')],['État',data.get('condition')],['Construction',data.get('year')],['Occupation',data.get('occupation')],['Diagnostics',data.get('diagnostics')],['DPE',data.get('dpe')],['Mandat',data.get('mandate')],['Type de location',data.get('rentalType')],['Charges mensuelles',data.get('charges')?money(Number(data.get('charges'))):''],['Propriétaire',[data.get('ownerFirstName'),data.get('owner')].filter(Boolean).join(' ')+' (privé)'],['Téléphone',data.get('ownerPhone')],['E-mail',data.get('email')],['Visites',data.get('availability')],['Contact préféré',data.get('preferred')]];const [main,...others]=depositPhotos;showModal(`<p class="eyebrow">Prévisualisation · non publié</p><h2 id="detail-title">${esc(data.get('title'))}</h2><p class="price">${money(Number(data.get('price')||data.get('rent')))}${data.get('transaction')==='Location'?' / mois':''}</p>${main?`<div class="preview-gallery"><img class="preview-main" src="${main.url}" alt="Photo principale : ${esc(main.name)}">${others.length?`<div class="photo-strip">${others.map((ph,i)=>`<img src="${ph.url}" alt="Photo ${i+2} : ${esc(ph.name)}">`).join('')}</div>`:''}</div>`:''}<dl>${rows.filter(([,v])=>v!==null&&v!=='').map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><p>${esc(data.get('description'))}</p><div class="chips">${data.getAll('features').map(f=>pill(f)).join('')}</div><p class="notice">Cette fiche n’a pas été enregistrée. Les coordonnées du propriétaire restent privées et ne seront jamais affichées dans le Hub.</p>`);}
function bindForm(){const f=$('deposit-form');f.addEventListener('change',conditions);f.addEventListener('submit',preview);conditions();$('photos').addEventListener('change',event=>{const files=[...event.target.files];const room=maxDepositPhotos-depositPhotos.length;const accepted=files.filter(f=>['image/jpeg','image/png','image/webp'].includes(f.type)&&f.size<=5*1024*1024).slice(0,Math.max(room,0));depositPhotos.push(...accepted.map(f=>({url:URL.createObjectURL(f),name:f.name})));event.target.value='';renderDepositPhotos();$('photo-status').textContent=`${depositPhotos.length} photo(s) · photo principale : ${depositPhotos[0]?.name||'aucune'}.`+(files.length!==accepted.length?' Certaines images ont été écartées (format, poids ou limite).':'');});}

function render(){
 $('detail').close();photoUrls.forEach(URL.revokeObjectURL);photoUrls=[];depositPhotos.forEach(ph=>URL.revokeObjectURL(ph.url));depositPhotos=[];document.body.classList.remove('nav-open');$('menu-toggle').setAttribute('aria-expanded','false');
 const parts=location.hash.slice(1).replace(/^\/+|\/+$/g,'').split('/');
 let route=parts[0]||'accueil';const id=parts[1];
 // Keep old bookmarks working while exposing a single property dossier.
 if(route==='projet'||route==='projets'){location.replace('#/'+(id?'bien/'+id:'biens'));return;}
 const privateRoute=route==='particulier';
 if(privateRoute)setViewMode('particulier');
 const clientMode=state.viewMode==='particulier',restricted=clientMode&&!privateRoute;
 document.body.classList.toggle('private-mode',clientMode);
 // Demo-only switch between the two interfaces; production will route each user to their own space.
 $('mode-switch').innerHTML=`<a href="#/" data-view-mode="pro" class="${clientMode?'':'active'}">Vue Pro</a><a href="#/particulier/bienvenue" data-view-mode="particulier" class="${clientMode?'active':''}">Vue Particulier</a>`;
 document.querySelector('.brand').href=clientMode?'#/particulier/bienvenue':'#/';
 $('brand-space').textContent=clientMode?'Particulier':'Pro';
 const current=parts.join('/');
 const proActive=key=>key===route||(key==='biens'&&route==='bien'&&mine(property(id)))||(key==='recherches'&&route==='recherche')||(key==='hub'&&(route==='fiche'||route==='bien'&&!mine(property(id))));
 const navItems=clientMode?privateSections.map(([key,name,ic])=>[key,name,ic,current===key]):[['accueil','Accueil','home',route==='accueil'],['journee','Ma journée','calendar',route==='journee'],...sections.map(([key,name,ic])=>[key,name,ic,proActive(key)])];
 $('navigation').innerHTML=navItems.map(([key,name,ic,active])=>`<a href="#/${key==='accueil'?'':key}" class="${active?'active':''}"${active?' aria-current="page"':''}>${icon(ic)}<span>${esc(name)}</span></a>`).join('');
 $('tabbar').innerHTML=navItems.filter(([key])=>!['notes','taches'].includes(key)).map(([key,name,ic,active])=>`<a href="#/${key==='accueil'?'':key}" class="${active?'active':''}">${icon(ic)}<span>${esc(name.replace('Hub Immobilier','Hub').replace('Ma journée','Journée').replace('Mes recherches','Recherches').replace('Mon Réseau','Réseau').replace('Confier mon bien','Vendre').replace('Déposer ma recherche','Rechercher'))}</span></a>`).join('');
 $('place').innerHTML=`<span class="place-icon">${icon('sun')}</span><span class="place-text"><small class="place-city">${esc(demoLocation.city)}</small><strong>${esc(demoLocation.temperature)} °C</strong></span>`;$('place').title=`${demoLocation.city} · ${demoLocation.temperature} °C · ${demoLocation.sky}`;
 $('tools-bar').innerHTML=clientMode?'':toolsBar();
 let html;
 if(restricted)html=proRestricted();
 else if(route==='particulier')html=!id?sellerDashboard():id==='recherche'?buyerDashboard():id==='confier'?privateDeposit():id==='bienvenue'?privateWelcome():id==='brief'?buyerBrief():missing();
 else if(route==='accueil')html=home();
 else if(route==='journee')html=myDay(id);
 else if(route==='hub')html=hub();
 else if(route==='biens')html=myPropertiesView();
 else if(route==='bien')html=mine(property(id))?dossier(property(id))+buyerProPanel(property(id))+synthesisPanel(property(id)):property(id)?.published?commercial(property(id)):missing();
 else if(route==='fiche')html=property(id)?.published?mine(property(id))?dossier(property(id))+buyerProPanel(property(id))+synthesisPanel(property(id)):commercial(property(id)):missing();
 else if(route==='recherches')html=searchesView();
 else if(route==='recherche')html=searchFile(id)?searchDossier(searchFile(id)):missing();
 else if(route==='notes')html=!id||mine(property(id))?notes(id):missing();
 else if(route==='taches')html=!id||mine(property(id))?tasks(id):missing();
 else if(route==='reseau')html=network();
 else if(route==='contact')html=contact(id||'');
 else if(route==='deposer')html=deposit();else html=missing();
 $('view').dataset.route=current;$('view').dataset.screen=restricted?'restricted':route;
 $('view').innerHTML='<p id="save-status" class="hint save-status" role="status" aria-live="polite"></p>'+html;
 if(restricted){document.title='Espace réservé · Li.La';$('view').focus({preventScroll:true});window.scrollTo(0,0);return;}
 if((route==='bien'||route==='fiche')&&mine(property(id)))bindSynthesis(property(id));
 if(route==='recherche'&&searchFile(id))bindSearchSynthesis(searchFile(id));
 document.title=($('view').querySelector('h1')?.textContent||'Cockpit')+' · Li.La';
 if(route==='hub'){['hub-query','hub-type','hub-budget'].forEach(id=>$(id).addEventListener('input',filterHub));filterHub();}
 if(route==='reseau'){['query','city','typology','trade','job'].forEach(key=>$('network-'+key).addEventListener('input',filterNetwork));filterNetwork();}
 if(route==='deposer')bindForm();
 if(route==='particulier'&&id==='confier')bindPrivateDeposit();
 if(route==='particulier'&&id==='brief')bindBuyerBrief();
 $('view').focus({preventScroll:true});window.scrollTo(0,0);
}
document.addEventListener('click',event=>{
 const mode=event.target.closest('[data-view-mode]');if(mode){setViewMode(mode.dataset.viewMode);if(location.hash===mode.getAttribute('href'))render();}
 const v=event.target.closest('[data-visitor]');if(v)visitor(v.dataset.visitor);
 const agentButton=event.target.closest('[data-agent]');if(agentButton)agentPanel(agentButton.dataset.agent);
 const networkAgent=event.target.closest('[data-network-agent]');if(networkAgent)addAgentToNetwork(networkAgent.dataset.networkAgent);
 const add=event.target.closest('[data-add]');if(add)addDialog(add.dataset.add,{property:add.dataset.property,search:add.dataset.search,contact:add.dataset.contact});
 if(event.target.closest('#quick-add'))quickAdd();
 if(event.target.closest('[data-calendar-connect]'))calendarConnectDialog();
 if(event.target.closest('[data-calendar-confirm]'))connectCalendar();
 if(event.target.closest('[data-calendar-disconnect]'))disconnectCalendar();
 if(event.target.closest('#menu-toggle')){const open=document.body.classList.toggle('nav-open');$('menu-toggle').setAttribute('aria-expanded',String(open));}
 if(event.target.closest('[data-cancel]'))$('detail').close();
 if(event.target.closest('[data-tools-config]'))toolsConfig();
 if(event.target.closest('[data-tools-reset]')){state.tools=null;state.docTool='gamma';save();$('detail').close();$('tools-bar').innerHTML=toolsBar();}
 if(event.target.closest('[data-new-search]'))showModal('<p class="eyebrow">Mes recherches</p><h2 id="detail-title">Nouvelle recherche</h2><p>Le formulaire professionnel de mandat de recherche sera intégré à partir du cahier des charges à venir.</p><div class="actions"><button type="button" data-cancel class="primary">Compris</button></div>');
 const chip=event.target.closest('[data-typology-chip]');if(chip&&$('network-typology')){$('network-typology').value=chip.dataset.typologyChip;filterNetwork();}
 const jump=event.target.closest('[data-jump]');if(jump)$(jump.dataset.jump)?.scrollIntoView({behavior:'smooth',block:'start'});
 if(event.target.closest('[data-synthesis-scroll]'))$('synthesis-panel')?.scrollIntoView({behavior:'smooth',block:'start'});
 const thumb=event.target.closest('[data-gallery-src]');if(thumb){const scope=thumb.closest('.gallery-scope');const img=scope?.querySelector('[data-gallery] img');if(img)img.src=thumb.dataset.gallerySrc;scope?.querySelectorAll('[data-gallery-src]').forEach(b=>b.classList.toggle('active',b===thumb));}
 const photoOp=event.target.closest('[data-photo-op]');if(photoOp)photoOperation(photoOp.dataset.photoOp,Number(photoOp.dataset.photoIndex));
 const sellerResponse=event.target.closest('[data-seller-response]');if(sellerResponse){const visit=state.visits.find(v=>v.id===sellerResponse.dataset.visitId&&sellerVisit(v));if(visit&&['Confirmée','Indisponible'].includes(sellerResponse.dataset.sellerResponse)){visit.sellerResponse=sellerResponse.dataset.sellerResponse;save();render();}}
 const buyerAction=event.target.closest('[data-buyer-action]');if(buyerAction&&searchProposals(demoBuyerSearch.searchId).some(m=>m.property===buyerAction.dataset.buyerProperty)&&['Intéressé','Refusé','Visite programmée','Favori'].includes(buyerAction.dataset.buyerAction)){state.buyerStatuses[buyerAction.dataset.buyerProperty]=buyerAction.dataset.buyerAction;save();render();}
 const proBuyerStatus=event.target.closest('[data-pro-buyer-status]');if(proBuyerStatus&&mine(property(proBuyerStatus.dataset.buyerProperty))&&searchProposals(demoBuyerSearch.searchId).some(m=>m.property===proBuyerStatus.dataset.buyerProperty)&&proBuyerStatus.dataset.proBuyerStatus==='Offre en cours'){state.buyerStatuses[proBuyerStatus.dataset.buyerProperty]='Offre en cours';save();render();}
 if(event.target.closest('[data-private-agent]'))privateAgentPanel();
});
document.addEventListener('change',event=>{
 if(event.target.matches('[data-task]')){const task=state.tasks.find(t=>t.id===event.target.dataset.task);if(task){task.status=event.target.checked?'Terminée':'À faire';save();render();}}
 if(event.target.matches('[data-doc-tool]')){state.docTool=event.target.value;save();const t=docTool();document.querySelectorAll('.create-doc').forEach(a=>{a.href=t.url;a.querySelector('small').textContent=t.name;});document.querySelectorAll('[data-doc-tool]').forEach(s=>s.value=t.id);}
});
$('detail').querySelector('.close').addEventListener('click',()=>$('detail').close());
window.addEventListener('hashchange',render);render();
